	return dict.T("dlv.watched") + " " + strconv.Itoa(watched) + " \u00b7 " + dict.T("dlv.withDriver") + " " + strconv.Itoa(withDriver) + " \u00b7 " + dict.T("dlv.finished") + " " + strconv.Itoa(terminal)
